// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    Log lg;

    function setUp() public { lg = new Log(); c = new MY_BANK(address(lg)); }

    function testFuzz_property(address actor, uint256 amount, uint256 warpTo) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 100 ether);
        warpTo = bound(warpTo, block.timestamp + 1, block.timestamp + 365 days);
        vm.warp(warpTo);
        vm.deal(actor, amount);
        uint256 lenBefore = historyLen();
        vm.prank(actor);
        c.Put{value: amount}(0);

        uint256 lenAfter = historyLen();
        string memory data;
        address snd;
        uint256 val;
        uint256 tim;
        if (lenAfter > 0) {
            (snd, data, val, tim) = lg.History(lenAfter - 1);
        }
        assertTrue(
            lenAfter == lenBefore + 1 &&
            snd == actor &&
            val == amount &&
            tim == warpTo &&
            keccak256(bytes(data)) == keccak256(bytes("Put")),
            "Put must record a complete log entry"
        );
    }

    function historyLen() internal view returns (uint256) {
        // History is a public array; probe its length by scanning until out of range.
        uint256 i = 0;
        while (true) {
            try lg.History(i) returns (address, string memory, uint256, uint256) {
                i++;
            } catch {
                return i;
            }
        }
    }
}
